#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, md;
    cin >> n >> m >> md;
    vector<long long> fact(n + 1, 1), inv_fact(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % md;
    }
    auto mod_pow = [&](long long base, int exp) {
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = res * base % md;
            base = base * base % md;
            exp >>= 1;
        }
        return res;
    };
    inv_fact[n] = mod_pow(fact[n], md - 2);
    for (int i = n; i >= 1; --i) {
        inv_fact[i - 1] = inv_fact[i] * i % md;
    }
    auto nCr = [&](int a, int b) {
        return fact[a] * inv_fact[b] % md * inv_fact[a - b] % md;
    };
    vector<int> g(n + 1, 1), f(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int now = (int)(nCr(i - 1, j - 1) * (long long)(i + 1) % md);
            g[i] = (g[i] + (long long)g[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)f[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)g[j - 1] * f[i - j] % md * now) % md;
            int add_value = ((j - 1) * j / 2 + (i - j) * (i - j + 1) / 2);
            f[i] = (f[i] + (long long)nCr(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_value) % md;
        }
    }
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    vector<vector<vector<int>>> dp2(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    dp[0][0][1] = 0; dp2[0][0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            dp[i][j][1] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
            dp2[i][j][1] = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
            for (int k = 1; k <= j; ++k) {
                int c = (int)(nCr(j, k));
                int val1 = (int)((long long)dp2[i - k][j - k][1] * f[k] % md);
                int val2 = (int)((long long)dp[i - k][j - k][1] * g[k] % md);
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val1) % md;
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val2) % md;
                dp2[i][j][0] = (dp2[i][j][0] + (long long)c * val2) % md;
            }
        }
    }
    printf("%d\n", (dp[n][m][0] + dp[n][m][1]) % md);
    return 0;
}
